const e=JSON.parse(JSON.stringify($input.first().json)),issues=[];
for(const f of e.regulatory.findings) if(!Array.isArray(f.evidence_ids)||!Array.isArray(f.missing_information)||typeof f.explanation!=='string'||!['unknown','satisfied','not_satisfied','not_assessed'].includes(f.condition_result))issues.push('Malformed regulatory finding');
for(const f of e.toxicology.findings) if(!Array.isArray(f.hazards)||f.hazards.some(h=>!h||!Array.isArray(h.evidence_ids)||typeof h.label!=='string')||f.consumer_risk!=='not_assessable')issues.push('Malformed toxicology finding');
if(!['verified','claimed','not_verified','conflicting'].includes(e.ethics.status)||!Array.isArray(e.ethics.evidence_ids)||typeof e.ethics.explanation!=='string')issues.push('Malformed ethics finding');
