return JSON.stringify({corpus_version:e.evidence_pack.corpus_version,as_of:e.evidence_pack.as_of,sources,rules:e.evidence_pack.rules,lookup_log:e.evidence_pack.lookup_log});

const before=$("Live - Build draft").first().json;
const raw=$input.first().json;
let obj;
try {obj=typeof raw.output==='string'?JSON.parse(raw.output):raw.output;}catch(err){obj=null;}
const e=JSON.parse(JSON.stringify(before));
if(!obj||typeof obj!=='object'||Array.isArray(obj)) {e.status='needs_review';e.error={code:'AGENT_JSON',message:'validator did not return a JSON object.'};}
else {e["validator"]=obj;e.agent_trace=e.agent_trace||{};e.agent_trace["validator"]=raw.intermediateSteps||[];}
return [{json:e}];

const e=JSON.parse(JSON.stringify($input.first().json)), issues=[];
const p=e.evidence_pack, refs=new Map(p.sources.map(s=>[s.evidence_id,s]));
function refsOk(ids,ingredient,kind) {
 if(!Array.isArray(ids)) {issues.push('Citation array missing');return;}
 for(const id of ids){
  const s=refs.get(id);
  if(!s){issues.push('Unknown evidence ID: '+id);continue;}
  if(ingredient && !s.ingredient_ids.includes(ingredient)) issues.push('Wrong substance for '+id);
  if(kind && s.kind!==kind) issues.push('Wrong source category for '+id);
 }
}
for(const f of e.draft.regulatory.findings){
 refsOk(f.evidence_ids,f.ingredient_id,'regulation');
 if(!['conditional','prohibited','no_rule_found_in_snapshot','not_assessed','conflicting'].includes(f.regulatory_status)) issues.push('Invalid regulatory status');
 if(!['not_assessed','no_rule_found_in_snapshot'].includes(f.regulatory_status)&&!f.evidence_ids.length) issues.push('Regulatory claim lacks evidence');
 const rules=p.rules.filter(r=>r.ingredient_id===f.ingredient_id);
 const ing=e.ingredients.find(i=>i.ingredient_id===f.ingredient_id);
 if(['conditional','prohibited','conflicting'].includes(f.regulatory_status) && !rules.some(r=>r.rule_state===f.regulatory_status && r.evidence_ids.some(id=>f.evidence_ids.includes(id))))
   issues.push('Regulatory status lacks a matching exact rule');
 if(rules.some(r=>r.concentration_required) && ing?.concentration_percent==null && f.condition_result!=='unknown')
   issues.push('Missing concentration must remain unknown');
 if(f.condition_result==='satisfied'&&!rules.some(r=>r.condition_result==='satisfied')) issues.push('Conditions were not verified by exact rules');
 if(f.regulatory_status==='no_rule_found_in_snapshot'&&!p.lookup_log?.some(l=>l.ingredient_id===f.ingredient_id&&l.exact_lookup_complete))
   issues.push('Negative result lacks exact-lookup log');
}
for(const f of e.draft.toxicology.findings){
 for(const h of f.hazards) refsOk(h.evidence_ids,f.ingredient_id,'toxicology');
 if(f.hazards.some(h=>!h.evidence_ids.length)) issues.push('Hazard claim lacks evidence');
 if(f.consumer_risk!=='not_assessable') issues.push('v0 does not calculate consumer risk');
}
refsOk(e.draft.ethics.evidence_ids,null,null);
if(e.draft.ethics.status==='verified'&&!e.draft.ethics.evidence_ids.some(id=>refs.get(id)?.kind==='certification'))
 issues.push('Verified ethics requires independent certification');
if(['claimed','verified','conflicting'].includes(e.draft.ethics.status)&&!e.draft.ethics.evidence_ids.length)
 issues.push('Ethics claim lacks evidence');
if((p.is_synthetic || p.sources.some(s=>s.is_synthetic!==false))) issues.push('Synthetic or unmarked evidence in live mode');
if(e.validator?.valid!==true) issues.push('AI validator did not accept the draft');
if((!Array.isArray(e.validator?.issues)||e.validator.issues.length||!Array.isArray(e.validator?.unsupported_evidence_ids)||e.validator.unsupported_evidence_ids.length)) issues.push('AI validator has unresolved issues');
e.validation={passed:issues.length===0,issues:[...new Set(issues)],semantic_check:'AI validator; not a proof of truth'};
e.status=issues.length?'needs_review':'completed';
if(!issues.length) e.report=e.draft;
else delete e.report;
return [{json:e}];

const e=$input.first().json;
return [{json:{schema_version:'0.1',request_id:e.request_id,mode:e.mode,origin:e.origin||'manual',
  status:e.status,report:e.status==='completed'?e.report:null,
  next_action:e.next_action||null,error:e.error||null,validation:e.validation||null,
}}];

const e=JSON.parse(JSON.stringify($input.first().json));
if(e.config.service_base_url.includes('.invalid')||!e.corpus.manifest_approved||!e.corpus.documents.length||!e.corpus.embedding.dimensions)
 throw new Error('Configure the ingestion service, approved document manifest, embedding revision and vector dimensions before running.');
return [{json:e}];

const before=$('Corpus - prepare manifest').first().json, r=$input.first().json;
const e={...before,status:'unavailable'};
if(r.status==='completed'&&r.corpus?.activated_version){
 e.status='completed';e.result={corpus_version:r.corpus.activated_version,counts:r.corpus.counts,checks:r.corpus.checks};
}else e.error={code:'CORPUS_NOT_ACTIVATED',message:'Corpus activation was not confirmed; keep the previous version.'};
return [{json:e}];

const e=JSON.parse(JSON.stringify($input.first().json));
if(!e.config.live_integrations_ready||e.config.service_base_url.includes('.invalid')){
 e.status='setup_required';e.next_action={type:'configure_corpus_service',message:'Configure the trusted service URL, a reviewed manifest and a pinned embedding model.'};
}else if(!e.corpus?.manifest_approved||!e.corpus?.documents?.length||!e.corpus?.embedding?.dimensions){
 e.status='needs_input';e.next_action={type:'supply_manifest',message:'Set corpus_manifest in Run settings with approved documents and embedding model/revision/dimensions.'};
}
return [{json:e}];

const e=JSON.parse(JSON.stringify($input.first().json));
e.evaluation=e.evaluation_input;
if(!e.evaluation||!Array.isArray(e.evaluation.questions)||!e.evaluation.questions.length||!Array.isArray(e.evaluation.runs)||!e.evaluation.runs.length){
 e.status='needs_input';e.next_action={type:'supply_evaluation_runs',message:'Supply human-labelled questions and recorded rankings for each retrieval configuration in evaluation_input.'};
}else e.evaluation.mode='measured';
return [{json:e}];

const e=JSON.parse(JSON.stringify($input.first().json));
const configs={};
for(const r of e.runs){
 const q=e.questions.find(q=>q.question_id===r.question_id);
 if(!q)throw new Error('Unknown question_id '+r.question_id);
 const relevant=new Set(q.relevant_unit_ids||[]);
 if(!['answerable','unanswerable'].includes(q.answerability))throw new Error('Ground truth not labelled for '+q.question_id);
 const acc=configs[r.config_id] ||= {answerable_n:0,unanswerable_n:0,recall3:0,recall5:0,hit3:0,hit5:0,mrr:0,abstention_correct:0};
 if(q.answerability==='unanswerable'){
   acc.unanswerable_n++;if(r.abstained===true)acc.abstention_correct++;continue;
 }
 if(!relevant.size)throw new Error('Answerable question needs gold source units: '+q.question_id);
 if(!Array.isArray(r.ranked_results))throw new Error('ranked_results missing');
 const ids=r.ranked_results.map(x=>x.source_unit_id);
 function found(k){return new Set(ids.slice(0,k).filter(id=>relevant.has(id))).size;}
 const rank=ids.findIndex(id=>relevant.has(id));
 acc.answerable_n++;acc.recall3+=found(3)/relevant.size;acc.recall5+=found(5)/relevant.size;
 acc.hit3+=Number(found(3)>0);acc.hit5+=Number(found(5)>0);acc.mrr+=rank<0?0:1/(rank+1);
}
// Paired comparison: each configuration must contain exactly the same labelled questions once.
const expected=e.questions.map(q=>q.question_id).sort().join('|');
for(const config of Object.keys(configs)){
 const actual=e.runs.filter(r=>r.config_id===config).map(r=>r.question_id).sort().join('|');
 if(actual!==expected)throw new Error('Unpaired, missing or duplicate questions in '+config);
}
if(!Object.keys(configs).length)throw new Error('No runs to evaluate');
const results=Object.entries(configs).map(([config_id,a])=>({config_id,answerable_questions:a.answerable_n,
 recall_at_3:a.answerable_n?a.recall3/a.answerable_n:null,recall_at_5:a.answerable_n?a.recall5/a.answerable_n:null,
 hit_at_3:a.answerable_n?a.hit3/a.answerable_n:null,hit_at_5:a.answerable_n?a.hit5/a.answerable_n:null,
 mrr:a.answerable_n?a.mrr/a.answerable_n:null,unanswerable_questions:a.unanswerable_n,
 abstention_accuracy:a.unanswerable_n?a.abstention_correct/a.unanswerable_n:null}));
return [{json:{mode:e.mode,results,
 note:'Recall uses the fraction of relevant source units retrieved in top-k chunks; hit rate asks whether any relevant unit was found. Duplicates do not inflate recall. MRR uses the first relevant chunk rank.'}}];

const e=$input.first().json;
const origin=e.origin||$('Trusted configuration and request').first().json.origin;
